CustomField.formula:
/*COE*/ IF( AND ( SBQQ__PricebookId__c == '01s7V000000NyMZQA0', Renewal_Roll_up_Amount__c > 0 , SBQQ__NetAmount__c > 0), "COE, ", "") &
/*DEAL DESK APPROVER*/ IF( SBQQ__PricebookId__c == '01s7V000000NyMZQA0' &&
( AND( TEXT( End_User_Account__r.Type ) <> "Customer", Max_Quantity__c < 500, Includes_TaaS_Bundle__c)) ||
( AND( TEXT( End_User_Account__r.Type ) <> "Customer", Max_Quantity__c < 300, Includes_On_Prem_Bundle__c)) ||
Ignore_Partner_Margin__c || Max_Bundle_Quantity__c < 100 || Max_Bundle_Quantity__c > 10000 ||
AND ( SBQQ__PricebookId__c <> '01s7V000000NyMZQA0', SBQQ__PricebookId__c <> '01s0e000000NxxjAAC',
(Renewal_Roll_up_Amount__c > 0) ||
((Account_Type__c == "Prospect" || Account_Type__c == "Former Customer"))
&& Core_Quantity__c < 10000)|| TEXT(PaymentTypeNew__c)='Custom' || Payment_Term_Override__c|| Max_Trial_Term_Rollup__c > 6|| Converge_Discount__c > 0.50 || Hardware_Discount__c > 0.45 || Account_Contracted_Price__c > 0 || Restricted_SKUs__c > 0 , "Deal Desk Approver, ", "") &
/*ESO DISCOUNT EMEA*/ IF( ESR_Product_Discount__c > 0.10, "ESO RD, ", "") &
/*ESO DISCOUNT ALL*/ IF( OR ( ESR_Product_Discount__c > 0.50, Max_FOC_Term_Rollup__c >0), "Russ Slaten, ", "") &
/*DEAL DESK APPROVER LEAD*/ IF( AND ( SBQQ__PricebookId__c <> '01s7V000000NyMZQA0', SBQQ__PricebookId__c <> '01s0e000000NxxjAAC'
|| (Core_Quantity__c < 10000 && ( Account_Type__c == "Prospect" || Account_Type__c == "Customer" )) || ( No_of_End_Points_Quote_Score__c > 50000)), "Deal Desk Approver Lead, ", "") &
/*AVP*/ IF( AND ( SBQQ__PricebookId__c <> '01s7V000000NyMZQA0', SBQQ__PricebookId__c <> '01s0e000000NxxjAAC' ) || AND ( SBQQ__PricebookId__c <> '01s7V000000NyMZQA0', SBQQ__PricebookId__c <> '01s0e000000NxxjAAC', No_of_End_Points_Quote_Score__c > 25000, No_of_End_Points_Quote_Score__c <= 50000 ) || AND ( SBQQ__PricebookId__c <> '01s7V000000NyMZQA0', SBQQ__PricebookId__c <> '01s0e000000NxxjAAC', No_of_End_Points_Quote_Score__c > 50000), "AVP Approver, ", "") &
""
